// Native tool-call grammars: each model family's call syntax (Muse's atem
// blocks, Qwen's JSON and Qwen3-Coder's XML calls, Nemotron Nano's
// <TOOLCALL> list, Mistral's [TOOL_CALLS], Harmony's channels, Gemma 4's
// call:NAME{...}) compiled into the same node tree schema.c's validator
// runs. Arguments compile through schema.c's JSON-schema compiler; the
// grammars build the protocol around them from the node constructors in
// schema_int.h. Nothing here runs per generated byte.
#include "schema_int.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// A sequence is an internal composition node: its children are the existing
// literal and JSON-value machines, consumed in order. It is deliberately not
// a second grammar engine; atem is compiled into the same snode/sval stack.
static snode *atem_seq(int count) {
    snode *n = sn_new(SN_SEQ);
    if (!n) return NULL;
    n->props = calloc((size_t)count, sizeof(*n->props));
    if (!n->props) { schema_free(n); return NULL; }
    n->n_props_cap = count;
    return n;
}

static snode *atem_lit(const char *s) {
    snode *n = sn_new(SN_ENUM);
    if (!n) return NULL;
    n->lits = calloc(1, sizeof(*n->lits));
    if (!n->lits) { schema_free(n); return NULL; }
    n->lits[0] = strdup(s);
    if (!n->lits[0]) { schema_free(n); return NULL; }
    n->n_lits = 1;
    if (!enum_index(n)) { schema_free(n); return NULL; }
    n->whitespace_significant = true;
    return n;
}

// The opener of a turn's FIRST native call, with the blank line a reasoning
// model writes after `</think>` (Qwen3's template renders `</think>\n\n` +
// content): the opener alone, or behind one or two newlines, and nothing
// else. A literal opener vetoed that newline and pushed the model straight
// to the call, off its own distribution (R4.26.19(d)); a raw gap would also
// admit text, and a stop at a raw tail could end a required turn callless.
static snode *native_lead_lit(const char *opener) {
    snode *n = sn_new(SN_ENUM);
    if (!n) return NULL;
    n->lits = calloc(3, sizeof(*n->lits));
    if (!n->lits) { schema_free(n); return NULL; }
    size_t len = strlen(opener);
    for (int k = 0; k < 3; k++) {
        char *s = malloc(len + (size_t)k + 1);
        if (!s) { schema_free(n); return NULL; }
        memset(s, '\n', (size_t)k);
        memcpy(s + k, opener, len + 1);
        n->lits[n->n_lits++] = s;
    }
    if (!enum_index(n)) { schema_free(n); return NULL; }
    n->whitespace_significant = true;
    return n;
}

static snode *atem_raw(const char *sentinel) {
    snode *n = sn_new(SN_RAW);
    if (!n) return NULL;
    n->sentinel = strdup(sentinel);
    if (!n->sentinel) { schema_free(n); return NULL; }
    n->sentinel_len = (int)strlen(sentinel);
    return n;
}

static snode *atem_raw_bounded(const char *sentinel, int max_bytes) {
    snode *n = atem_raw(sentinel);
    if (n) n->max_items = max_bytes;
    return n;
}

static bool atem_seq_add(snode *seq, snode *child) {
    if (!child) return false;
    // The capacity is chosen at atem_seq() and the adds are written by hand,
    // several of them behind conditionals (`atem_seq(lead ? 4 : 3)`), so the
    // two can drift apart in a later edit. Nothing here bounds-checked that
    // pairing, and props is exact-sized: one add too many was a silent heap
    // write past the allocation. The container answers for its own capacity
    // now and refuses instead, which fails the schema compile loudly.
    //
    // On that refusal an inline-constructed child (`atem_seq_add(seq,
    // atem_lit("x"))`) leaks, because no caller holds a pointer to free. That
    // is deliberate: the path is a programming error that no call site reaches
    // today, and a one-node leak on an impossible branch is strictly better
    // than the heap write past the allocation it replaces.
    if (seq->n_props >= seq->n_props_cap) return false;
    // see sval_ws_is_content: the container answers for a significant child
    // whose frame does not exist yet
    if (child->whitespace_significant) seq->whitespace_significant = true;
    seq->props[seq->n_props++] = child;
    return true;
}

// An ordered native-protocol member list is the non-JSON analogue of SN_OBJ:
// each position carries one value subtree, required members cannot be skipped,
// and optional members may be omitted without copying every possible suffix.
// `keys` are the prefixes used before the first emitted member, `next_keys`
// the prefixes used after one. The validator matches all skippable prefixes
// through the next required member in parallel, so common multi-byte prefixes
// remain exact without an ENUM+COND expansion per possible position.
static snode *native_members_new(int count, const char *close) {
    snode *n = sn_new(SN_MEMBERS);
    if (!n) return NULL;
    n->keys = calloc((size_t)count, sizeof(*n->keys));
    n->key_len = calloc((size_t)count, sizeof(*n->key_len));
    n->next_keys = calloc((size_t)count, sizeof(*n->next_keys));
    n->next_key_len = calloc((size_t)count, sizeof(*n->next_key_len));
    n->props = calloc((size_t)count, sizeof(*n->props));
    n->req = calloc((size_t)count, sizeof(*n->req));
    n->sentinel = strdup(close);
    if ((count && (!n->keys || !n->key_len || !n->next_keys ||
                   !n->next_key_len || !n->props || !n->req)) ||
        !n->sentinel) {
        schema_free(n);
        return NULL;
    }
    n->sentinel_len = (int)strlen(close);
    n->n_props = count;
    n->whitespace_significant = true;
    return n;
}

static bool native_member_set(snode *n, int at, const char *first,
                              const char *next, snode *value) {
    n->keys[at] = strdup(first);
    n->next_keys[at] = strdup(next);
    if (!n->keys[at] || !n->next_keys[at] || !value) {
        return false;
    }
    n->key_len[at] = (int)strlen(first);
    n->next_key_len[at] = (int)strlen(next);
    n->props[at] = value;
    return true;
}

// Mark the required names after a compiler has put the properties in its own
// protocol order (declaration order for Muse, dictsort order for gemma4).
// This mirrors the generic object compiler's exact required-name check rather
// than interpreting a misspelled required entry as optional.
static bool native_members_required(snode *n, jv *params, jv *props,
                                    const int *order,
                                    char *err, int errcap) {
    jv *req = params ? jv_get(params, "required") : NULL;
    if (!req) return true;
    if (req->type != J_ARR) {
        snprintf(err, errcap, "required must be an array");
        return false;
    }
    for (int r = 0; r < req->n; r++) {
        const char *key = jv_str(req->items[r], NULL);
        int found = -1;
        for (int i = 0; key && i < props->n; i++) {
            int pi = order ? order[i] : i;
            if (!strcmp(props->keys[pi], key)) { found = i; break; }
        }
        if (found < 0) {
            snprintf(err, errcap, "required key '%s' not in properties",
                     key ? key : "?");
            return false;
        }
        n->req[found] = true;
    }
    return true;
}

// ATEM spells strings as raw bytes, without JSON quotes. A free string is
// representable by SN_RAW and a string enum/const by an enum whose literals
// are the decoded strings. Length/pattern constraints need a different raw
// machine, so the native protocol declines them and its caller selects the
// generic JSON envelope instead.
static snode *atem_string_value(jv *schema, const char *name, bool *raw,
                                char *err, int errcap) {
    snode *json = compile_node(schema, err, errcap, 0);
    if (!json) return NULL;
    if (json->kind == SN_STR && json->min_items == 0 &&
        json->max_items < 0 && json->n_pats == 0) {
        schema_free(json);
        *raw = true;
        return atem_raw("</atem:parameter>");
    }
    if (json->kind != SN_ENUM) {
        snprintf(err, errcap,
                 "atem raw string parameter '%s' has constraints that native "
                 "syntax cannot enforce", name);
        schema_free(json);
        return NULL;
    }
    snode *native = sn_new(SN_ENUM);
    if (!native) { schema_free(json); return NULL; }
    native->lits = calloc((size_t)json->n_lits, sizeof(*native->lits));
    if (!native->lits) { schema_free(native); schema_free(json); return NULL; }
    native->whitespace_significant = true;
    for (int i = 0; i < json->n_lits; i++) {
        jv *literal = json_parse(json->lits[i], strlen(json->lits[i]));
        const char *text = jv_str(literal, NULL);
        if (!text || !text[0] || strstr(text, "</atem:parameter>")) {
            snprintf(err, errcap,
                     "atem string enum parameter '%s' has an unrepresentable "
                     "native value", name);
            jv_free(literal); schema_free(native); schema_free(json);
            return NULL;
        }
        native->lits[native->n_lits] = strdup(text);
        jv_free(literal);
        if (!native->lits[native->n_lits]) {
            schema_free(native); schema_free(json); return NULL;
        }
        native->n_lits++;
    }
    schema_free(json);
    *raw = false;
    return native;
}

static snode *atem_tool_tail(jv *tool, char *err, int errcap) {
    jv *fn = jv_get(tool, "function");
    if (!fn) fn = tool;
    jv *params = jv_get(fn, "parameters");
    jv *props = params ? jv_get(params, "properties") : NULL;
    if (props && props->type != J_OBJ) {
        snprintf(err, errcap, "atem tool parameters.properties must be an object");
        return NULL;
    }
    if (props && props->n > 60) {
        snprintf(err, errcap, "atem tool has too many parameters (max 60)");
        return NULL;
    }
    snode *seq = atem_seq(2);
    if (!seq) goto oom;   // NOT a bare return: the caller prints this message
    if (!atem_seq_add(seq, atem_lit("\">\n"))) goto oom;
    snode *members = native_members_new(
        props ? props->n : 0, "</atem:invoke>\n</atem:function_calls>");
    if (!members) goto oom;
    for (int i = 0; props && i < props->n; i++) {
        jv *ty = jv_get(props->items[i], "type");
        const char *type = jv_str(ty, "");
        sbuf open = {0};
        sb_fmt(&open, "<atem:parameter name=\"%s\">", props->keys[i]);
        bool json_spelled = !strcmp(type, "object") || !strcmp(type, "array") ||
                            !strcmp(type, "integer") || !strcmp(type, "number") ||
                            !strcmp(type, "boolean") || !strcmp(type, "null");
        bool raw = false;
        snode *value = json_spelled
                     ? compile_node(props->items[i], err, errcap, 0)
                     : atem_string_value(props->items[i], props->keys[i], &raw,
                                         err, errcap);
        snode *tail = atem_seq(raw ? 2 : 3);
        if (open.failed || !value || !tail || !atem_seq_add(tail, value) ||
            (!raw &&
             !atem_seq_add(tail, atem_lit("</atem:parameter>"))) ||
            !atem_seq_add(tail, atem_lit("\n")) ||
            !native_member_set(members, i, open.s, open.s, tail)) {
            free(open.s);
            if (!tail || tail->n_props == 0) schema_free(value);
            schema_free(tail);
            schema_free(members);
            if (!err[0]) goto oom;
            schema_free(seq); return NULL;
        }
        free(open.s);
    }
    if (props && !native_members_required(members, params, props, NULL,
                                          err, errcap)) {
        schema_free(members); schema_free(seq); return NULL;
    }
    if (!atem_seq_add(seq, members)) { schema_free(members); goto oom; }
    return seq;
oom:
    if (!err[0]) snprintf(err, errcap, "out of memory compiling atem tools");
    schema_free(seq);
    return NULL;
}

snode *schema_compile_atem_tools(struct jv *tools, char *err, int errcap) {
    err[0] = 0;
    if (!tools || tools->type != J_ARR || tools->n <= 0 || tools->n > 60) {
        snprintf(err, errcap, "atem tools must be a non-empty array of at most 60 tools");
        return NULL;
    }
    snode *root = atem_seq(3);
    snode *names = sn_new(SN_ENUM);
    snode *choice = sn_new(SN_COND);
    if (!root || !names || !choice) goto fail;
    names->lits = calloc((size_t)tools->n, sizeof(*names->lits));
    choice->alts = calloc((size_t)tools->n, sizeof(*choice->alts));
    if (!names->lits || !choice->alts) goto fail;
    names->min_items = 1; // this enum selects the following conditional tail
    names->whitespace_significant = true;
    if (!atem_seq_add(root,
            atem_lit("<atem:function_calls>\n<atem:invoke name=\""))) goto fail;
    for (int i = 0; i < tools->n; i++) {
        jv *fn = jv_get(tools->items[i], "function");
        if (!fn) fn = tools->items[i];
        const char *name = jv_str(jv_get(fn, "name"), NULL);
        if (!name || !name[0]) {
            snprintf(err, errcap, "atem tool %d has no function name", i);
            goto fail;
        }
        names->lits[names->n_lits] = strdup(name);
        if (!names->lits[names->n_lits]) goto fail;
        names->n_lits++;
        choice->alts[choice->n_alts] = atem_tool_tail(tools->items[i], err, errcap);
        if (!choice->alts[choice->n_alts]) goto fail;
        choice->n_alts++;
    }
    if (!atem_seq_add(root, names)) goto fail;
    names = NULL;
    if (!atem_seq_add(root, choice)) goto fail;
    choice = NULL;
    return root;
fail:
    // one unwind label, and it supplies a reason when nobody else did:
    // both callers print this string, and a NULL with an empty message
    // reports a rejected request with no explanation at all
    if (!err[0]) snprintf(err, errcap, "out of memory compiling atem tools");
    schema_free(names); schema_free(choice); schema_free(root);
    return NULL;
}

bool schema_atem_constrainable(struct jv *tools, char *err, int errcap) {
    snode *probe = schema_compile_atem_tools(tools, err, errcap);
    if (!probe) return false;
    schema_free(probe);
    return true;
}

static snode *schema_compile_atem_turn_prefix(struct jv *tools, bool allow_user,
                                              const char *only_tool,
                                              struct jv *final_schema,
                                              const char *prefix,
                                              char *err, int errcap) {
    err[0] = 0;
    if (!tools || tools->type != J_ARR || tools->n <= 0 || tools->n > 59) {
        snprintf(err, errcap, "atem turn needs 1 to 59 tools");
        return NULL;
    }
    snode *root = atem_seq(prefix[0] ? 3 : 2);
    snode *names = sn_new(SN_ENUM), *choice = sn_new(SN_COND);
    if (!root || !names || !choice) goto fail;
    root->whitespace_significant = prefix[0] == ' ';
    int selected = 0;
    for (int i = 0; i < tools->n; i++) {
        jv *fn = jv_get(tools->items[i], "function"); if (!fn) fn = tools->items[i];
        const char *name = jv_str(jv_get(fn, "name"), NULL);
        if (!only_tool || (name && !strcmp(name, only_tool))) selected++;
    }
    if (!selected) { snprintf(err, errcap, "named atem tool is not declared"); goto fail; }
    int branches = selected + (allow_user ? 1 : 0);
    names->lits = calloc((size_t)branches, sizeof(*names->lits));
    choice->alts = calloc((size_t)branches, sizeof(*choice->alts));
    if (!names->lits || !choice->alts) goto fail;
    names->min_items = 1;
    names->whitespace_significant = true;
    choice->whitespace_significant = true;
    if (prefix[0] && !atem_seq_add(root, atem_lit(prefix))) goto fail;
    for (int i = 0; i < tools->n; i++) {
        jv *fn = jv_get(tools->items[i], "function");
        if (!fn) fn = tools->items[i];
        const char *name = jv_str(jv_get(fn, "name"), NULL);
        if (!name || !name[0]) { snprintf(err, errcap, "atem tool %d has no name", i); goto fail; }
        if (only_tool && strcmp(name, only_tool)) continue;
        names->lits[names->n_lits++] = strdup(name);
        snode *tail = atem_seq(3);
        if (!names->lits[names->n_lits - 1] || !tail ||
            !atem_seq_add(tail, atem_lit("<|message|><atem:function_calls>\n<atem:invoke name=\"")) ||
            !atem_seq_add(tail, atem_lit(name)) ||
            !atem_seq_add(tail, atem_tool_tail(tools->items[i], err, errcap))) {
            schema_free(tail); goto fail;
        }
        choice->alts[choice->n_alts++] = tail;
    }
    if (allow_user) {
        names->lits[names->n_lits++] = strdup("user");
        snode *answer = atem_seq(2);
        snode *answer_value = final_schema
                            ? compile_node(final_schema, err, errcap, 0)
                            : atem_raw("<|eot|>");
        if (!names->lits[names->n_lits - 1] || !answer ||
            !atem_seq_add(answer, atem_lit("<|message|>")) ||
            !atem_seq_add(answer, answer_value)) {
            schema_free(answer_value);
            schema_free(answer); goto fail;
        }
        choice->alts[choice->n_alts++] = answer;
    }
    if (!atem_seq_add(root, names)) goto fail;
    names = NULL;
    if (!atem_seq_add(root, choice)) goto fail;
    choice = NULL;
    return root;
fail:
    if (!err[0]) snprintf(err, errcap, "out of memory compiling atem turn");
    schema_free(names); schema_free(choice); schema_free(root);
    return NULL;
}

snode *schema_compile_atem_turn(struct jv *tools, bool allow_user,
                                const char *only_tool,
                                struct jv *final_schema,
                                enum atem_turn_start start,
                                char *err, int errcap) {
    // After a self-addressed reasoning turn the model closes it with <|eom|>
    // (a decoded-empty control the engine consumes) and opens the next turn
    // as `<|start|>assistant to=NAME<|message|>`: <|start|> is decoded-empty
    // too, so the bytes the grammar sees are `assistant to=`. The prefix used
    // to be empty, which rejected every real transition at its first byte
    // (the lab, 2026-09-16: finish "error" right after the self turn).
    if (start == ATEM_TURN_DIRECT || start == ATEM_TURN_AFTER_REASONING)
        return schema_compile_atem_turn_prefix(
            tools, allow_user, only_tool, final_schema,
            start == ATEM_TURN_DIRECT ? " to=" : "assistant to=", err, errcap);
    if (start != ATEM_TURN_EITHER) {
        snprintf(err, errcap, "invalid atem turn start");
        return NULL;
    }
    snode *direct = schema_compile_atem_turn_prefix(
        tools, allow_user, only_tool, final_schema, " to=", err, errcap);
    snode *after = direct ? schema_compile_atem_turn_prefix(
        tools, allow_user, only_tool, final_schema, "assistant to=", err, errcap) : NULL;
    snode *root = after ? sn_new(SN_UNION) : NULL;
    if (!root) {
        schema_free(direct); schema_free(after);
        if (!err[0]) snprintf(err, errcap, "out of memory compiling atem recipient turn");
        return NULL;
    }
    root->alts = calloc(2, sizeof(*root->alts));
    if (!root->alts) {
        schema_free(direct); schema_free(after); schema_free(root);
        snprintf(err, errcap, "out of memory compiling atem recipient turn");
        return NULL;
    }
    root->whitespace_significant = true;
    root->alts[root->n_alts++] = direct;
    root->alts[root->n_alts++] = after;
    return root;
}

// Free bytes allowed between two calls of one turn (a separator and the next
// opener), and after the last call a turn may carry (too few to spell one).
#define NATIVE_GAP_BYTES 16
#define NATIVE_END_BYTES 4

// After a complete Muse call in a parallel turn: end the turn or open the
// next call, at most `remaining` more. The model's trained form (template.c,
// assistant_calls_render) separates calls with `<|eom|><|start|>assistant`
// and ends the turn with `<|eot|>`. Both controls decode to no bytes, so the
// SEPARATOR is spelled in the grammar: a control token is admitted by its
// spelling (engine.c constraint_spelling_ok) and its spelling is what the
// validator consumes. The pair this replaced spelled only `assistant`, which
// refused the model's own `<|eom|>` and pushed it to type a turn header as
// text; on Muse-Glimmer-30B (CPU, required, 2026-10-09) it then repeated the
// first city as the second call in 5 of 6 turns. The gap is bounded to the
// separator plus a few bytes, the Qwen protocols' raw gap (native_more_calls):
// a stop there ends the turn, and past the last admitted call it is too short
// to spell another separator.
#define ATEM_CALL_SEP "<|eom|><|start|>assistant"
static snode *atem_more_calls(jv *tools, const char *only, int remaining,
                              char *err, int errcap) {
    snode *raw = atem_raw_bounded("<|eot|>", remaining
        ? (int)sizeof(ATEM_CALL_SEP) - 1 + NATIVE_END_BYTES : NATIVE_END_BYTES);
    if (!raw) goto oom;
    raw->whitespace_significant = true;
    if (!remaining) return raw;
    snode *seq = atem_seq(2);
    snode *call = seq ? schema_compile_atem_turn(tools, false, only, NULL,
                                                 ATEM_TURN_DIRECT, err, errcap)
                      : NULL;
    snode *tail = call ? atem_more_calls(tools, only, remaining - 1, err, errcap)
                       : NULL;
    raw->lits = calloc(1, sizeof(*raw->lits));
    raw->alts = calloc(1, sizeof(*raw->alts));
    if (!seq || !call || !tail || !raw->lits || !raw->alts ||
        !(raw->lits[0] = strdup(ATEM_CALL_SEP))) {
        schema_free(seq); schema_free(call); schema_free(tail); schema_free(raw);
        goto oom;
    }
    raw->n_lits = 1;
    atem_seq_add(seq, call);
    atem_seq_add(seq, tail);
    seq->whitespace_significant = true;
    raw->alts[raw->n_alts++] = seq;
    return raw;
oom:
    if (!err[0]) snprintf(err, errcap, "out of memory compiling parallel atem turn");
    return NULL;
}

snode *schema_compile_atem_parallel(struct jv *tools, const char *only_tool,
                                    char *err, int errcap) {
    // one to NATIVE_PARALLEL_MAX_CALLS calls; it was a fixed PAIR until
    // 2026-10-09 (see atem_more_calls)
    snode *root = atem_seq(2);
    snode *first = root ? schema_compile_atem_turn(
        tools, false, only_tool, NULL, ATEM_TURN_DIRECT, err, errcap) : NULL;
    snode *rest = first ? atem_more_calls(tools, only_tool,
                                          NATIVE_PARALLEL_MAX_CALLS - 1,
                                          err, errcap) : NULL;
    if (!root || !first || !rest) {
        schema_free(first); schema_free(rest); schema_free(root);
        if (!err[0]) snprintf(err, errcap, "out of memory compiling parallel atem turn");
        return NULL;
    }
    root->whitespace_significant = true;
    root->props[root->n_props++] = first;
    root->props[root->n_props++] = rest;
    return root;
}

// ------------------------------------------------------------- Qwen tools

static snode *qwen_call_tail(jv *tool, const char *close, char *err, int errcap) {
    jv *fn = jv_get(tool, "function");
    if (!fn) fn = tool;
    const char *name = jv_str(jv_get(fn, "name"), "tool");
    jv *params = jv_get(fn, "parameters");
    if (params && params->type != J_OBJ) {
        snprintf(err, errcap,
                 "Qwen tool %s parameters must be an object", name);
        return NULL;
    }
    snode *seq = atem_seq(3);
    snode *args = params ? compile_node(params, err, errcap, 0)
                         : atem_lit("{}");
    if (!seq || !args ||
        !atem_seq_add(seq, atem_lit("\", \"arguments\": ")) ||
        !atem_seq_add(seq, args) ||
        !atem_seq_add(seq, atem_lit(close))) {
        if (!seq || seq->n_props < 2) schema_free(args);
        schema_free(seq);
        if (!err[0]) snprintf(err, errcap,
                              "out of memory compiling Qwen call");
        return NULL;
    }
    seq->whitespace_significant = true;
    return seq;
}

// `lead` emits the opening `<tool_call>` marker. It is dropped when an ENUM
// upstream has already consumed the marker to discriminate a thought block
// from a call, exactly as g4_call's own lead flag works.
static snode *qwen_call(jv *tools, const char *only_tool, bool lead,
                        char *err, int errcap) {
    int selected = 0;
    for (int i = 0; i < tools->n; i++) {
        jv *fn = jv_get(tools->items[i], "function");
        if (!fn) fn = tools->items[i];
        const char *name = jv_str(jv_get(fn, "name"), NULL);
        if (!only_tool || (name && !strcmp(name, only_tool))) selected++;
    }
    if (!selected) {
        snprintf(err, errcap, "named Qwen tool is not declared");
        return NULL;
    }
    snode *root = atem_seq(lead ? 4 : 3);
    snode *names = sn_new(SN_ENUM), *choice = sn_new(SN_COND);
    if (!root || !names || !choice) goto fail;
    names->lits = calloc((size_t)selected, sizeof(*names->lits));
    choice->alts = calloc((size_t)selected, sizeof(*choice->alts));
    if (!names->lits || !choice->alts) goto fail;
    if (lead && !atem_seq_add(root, native_lead_lit("<tool_call>"))) goto fail;
    if (!atem_seq_add(root, atem_lit("\n{\"name\": \""))) goto fail;
    names->min_items = 1;
    names->whitespace_significant = true;
    choice->whitespace_significant = true;
    root->whitespace_significant = true;
    for (int i = 0; i < tools->n; i++) {
        jv *fn = jv_get(tools->items[i], "function");
        if (!fn) fn = tools->items[i];
        const char *name = jv_str(jv_get(fn, "name"), NULL);
        if (!name || !name[0]) {
            snprintf(err, errcap, "Qwen tool %d has no function name", i);
            goto fail;
        }
        if (only_tool && strcmp(name, only_tool)) continue;
        names->lits[names->n_lits] = strdup(name);
        if (!names->lits[names->n_lits]) goto fail;
        names->n_lits++;
        choice->alts[choice->n_alts] = qwen_call_tail(
            tools->items[i], "}\n</tool_call>", err, errcap);
        if (!choice->alts[choice->n_alts]) goto fail;
        choice->n_alts++;
    }
    if (!atem_seq_add(root, names)) goto fail;
    names = NULL;
    if (!atem_seq_add(root, choice)) goto fail;
    choice = NULL;
    return root;
fail:
    schema_free(names); schema_free(choice); schema_free(root);
    if (!err[0]) snprintf(err, errcap, "out of memory compiling Qwen call");
    return NULL;
}

// The turn's non-call alternative: a caller-supplied final schema, or plain
// prose terminated by the chatml stop marker.
static snode *qwen_or_final(snode *body, jv *final_schema,
                            char *err, int errcap) {
    snode *final = final_schema ? compile_node(final_schema, err, errcap, 0)
                                : atem_raw("<|im_end|>");
    snode *root = final ? sn_new(SN_UNION) : NULL;
    if (root) root->alts = calloc(2, sizeof(*root->alts));
    if (!root || !root->alts) {
        schema_free(body); schema_free(final); schema_free(root);
        if (!err[0]) snprintf(err, errcap,
                              "out of memory compiling Qwen turn");
        return NULL;
    }
    root->whitespace_significant = true;
    root->alts[root->n_alts++] = body;
    root->alts[root->n_alts++] = final;
    return root;
}


// Free assistant text with a native-call handoff. Unlike a catch-all final
// branch, seeing the FULL opener commits to the tool grammar even after prose.
// SN_RAW owns one optional marker/continuation pair (lits[0], alts[0]).
static snode *qwen_text_handoff(snode *call) {
    snode *raw=atem_raw("<|im_end|>");
    if (!raw) { schema_free(call); return NULL; }
    raw->lits=calloc(1,sizeof(*raw->lits));
    raw->alts=calloc(1,sizeof(*raw->alts));
    if (!raw->lits || !raw->alts) { schema_free(call);schema_free(raw);return NULL; }
    raw->lits[0]=strdup("<tool_call>");raw->n_lits=1;
    raw->alts[0]=call;raw->n_alts=1;
    if (!raw->lits[0] || !call) { schema_free(raw);return NULL; }
    raw->whitespace_significant=true;
    return raw;
}

static snode *qwen_text_calls(jv *tools, const char *only_tool, int remaining,
                              char *err, int errcap) {
    // past the last admitted call the turn ends: raw text there would let
    // an unvalidated call through the mapper, so the tail is too short to
    // spell an opener. It is raw, not the literal `<|im_end|>`: the model's
    // stop token decodes to no bytes and could never complete a literal.
    if (!remaining) return atem_raw_bounded("<|im_end|>", NATIVE_END_BYTES);
    snode *seq=atem_seq(2);
    snode *call=qwen_call(tools,only_tool,false,err,errcap);
    snode *tail=call ? qwen_text_calls(tools,only_tool,remaining-1,err,errcap) : NULL;
    if (!seq || !call || !tail) {
        schema_free(seq);schema_free(call);schema_free(tail);return NULL;
    }
    atem_seq_add(seq,call);atem_seq_add(seq,tail);
    return qwen_text_handoff(seq);
}

snode *schema_compile_qwen_turn(jv *tools, bool allow_final,
                                const char *only_tool, jv *final_schema,
                                bool allow_reasoning, bool parallel,
                                char *err, int errcap) {
    err[0] = 0;
    if (!tools || tools->type != J_ARR || tools->n <= 0 || tools->n > 60) {
        snprintf(err, errcap,
                 "Qwen tools must be a non-empty array of at most 60 tools");
        return NULL;
    }
    // free text with calls: as many as the envelope admits (its max_calls,
    // 8 in parallel and 1 without), then the turn ends
    if (allow_final && !final_schema)
        return qwen_text_calls(tools, only_tool, parallel ? 8 : 1, err, errcap);
    if (!allow_reasoning) {
        snode *call = qwen_call(tools, only_tool, true, err, errcap);
        if (!call || !allow_final) return call;
        return qwen_or_final(call, final_schema, err, errcap);
    }
    // Thought and call blocks BOTH open with '<', so they cannot be two
    // alternatives of a union -- pick_alt would resolve on that byte and the
    // second would be unreachable. One ENUM discriminates them instead,
    // exactly as gemma4's reasoning turn does, and the union below is left
    // with a single '<' branch against prose.
    snode *marked = atem_seq(2);
    snode *disc = sn_new(SN_ENUM), *choice = sn_new(SN_COND);
    snode *thought = NULL, *call = NULL, *after = NULL;
    if (!marked || !disc || !choice) goto fail;
    disc->lits = calloc(2, sizeof(*disc->lits));
    choice->alts = calloc(2, sizeof(*choice->alts));
    if (!disc->lits || !choice->alts) goto fail;
    disc->min_items = 1;
    disc->whitespace_significant = true;
    choice->whitespace_significant = true;
    marked->whitespace_significant = true;
    disc->lits[disc->n_lits++] = strdup("<think>");
    disc->lits[disc->n_lits++] = strdup("<tool_call>");
    if (!disc->lits[0] || !disc->lits[1]) goto fail;
    // Once the thought closes, what follows is an ordinary un-thought Qwen
    // turn, so the same compiler builds it. The sentinel carries the two
    // newlines the reference template writes after `</think>`, which is also
    // the form runner emits itself for enable_thinking=false.
    after = schema_compile_qwen_turn(tools, allow_final, only_tool,
                                     final_schema, false, parallel, err, errcap);
    thought = atem_seq(2);
    if (!thought || !after ||
        !atem_seq_add(thought, atem_raw("</think>\n\n")) ||
        !atem_seq_add(thought, after)) {
        // `after` is owned by `thought` only once both adds succeeded; an
        // atem_seq failure (thought NULL) used to skip the free and leak it
        if (!thought || thought->n_props < 2) schema_free(after);
        after = NULL;
        goto fail;
    }
    after = NULL;
    thought->whitespace_significant = true;
    call = qwen_call(tools, only_tool, false, err, errcap);
    if (!call) goto fail;
    choice->alts[choice->n_alts++] = thought; thought = NULL;
    choice->alts[choice->n_alts++] = call;    call = NULL;
    if (!atem_seq_add(marked, disc)) goto fail;
    disc = NULL;
    if (!atem_seq_add(marked, choice)) goto fail;
    choice = NULL;
    if (!allow_final) return marked;
    return qwen_or_final(marked, final_schema, err, errcap);
fail:
    if (!err[0]) snprintf(err, errcap, "out of memory compiling Qwen turn");
    schema_free(after); schema_free(thought); schema_free(call);
    schema_free(disc); schema_free(choice); schema_free(marked);
    return NULL;
}

// After a complete call in a required/named parallel turn: end the turn, or
// open another call, at most `remaining` more. This replaced a fixed PAIR:
// the turn had to carry exactly two calls, so a model with one call to make
// was forced to invent a second, and one with three lost the third.
//
// The gap is a raw tail bounded to a separator's worth of bytes: it ends at
// the stop marker, and the full `<tool_call>` opener hands off to the next
// constrained call. A raw tail is what lets the model's own stop token end
// the turn (constraint_token_ok admits a stop there; a stop token decodes to
// no bytes, so a LITERAL `<|im_end|>` in the grammar is unreachable for it,
// and a first version built that way ran every turn to the eighth call,
// inventing the rest). Past the last admitted call the tail is too short to
// spell an opener, so no unvalidated call can reach the mapper.
typedef snode *(*native_call_fn)(jv *tools, const char *only, bool lead,
                                 char *err, int errcap);
static snode *native_more_calls(native_call_fn mk, jv *tools, const char *only,
                                int remaining, char *err, int errcap) {
    snode *raw = atem_raw_bounded("<|im_end|>", remaining ? NATIVE_GAP_BYTES
                                                          : NATIVE_END_BYTES);
    if (!raw) goto oom;
    raw->whitespace_significant = true;
    if (!remaining) return raw;
    snode *seq = atem_seq(2);
    snode *call = seq ? mk(tools, only, false, err, errcap) : NULL;
    snode *tail = call ? native_more_calls(mk, tools, only, remaining - 1,
                                           err, errcap) : NULL;
    raw->lits = calloc(1, sizeof(*raw->lits));
    raw->alts = calloc(1, sizeof(*raw->alts));
    if (!seq || !call || !tail || !raw->lits || !raw->alts ||
        !(raw->lits[0] = strdup("<tool_call>"))) {
        schema_free(seq); schema_free(call); schema_free(tail); schema_free(raw);
        goto oom;
    }
    raw->n_lits = 1;
    atem_seq_add(seq, call);
    atem_seq_add(seq, tail);
    seq->whitespace_significant = true;
    raw->alts[raw->n_alts++] = seq;
    return raw;
oom:
    if (!err[0]) snprintf(err, errcap, "out of memory compiling parallel calls");
    return NULL;
}

static snode *native_parallel_calls(native_call_fn mk, jv *tools,
                                    const char *only, char *err, int errcap) {
    snode *root = atem_seq(2);
    snode *first = root ? mk(tools, only, true, err, errcap) : NULL;
    snode *rest = first ? native_more_calls(mk, tools, only,
                                            NATIVE_PARALLEL_MAX_CALLS - 1,
                                            err, errcap) : NULL;
    if (!root || !first || !rest) {
        schema_free(root); schema_free(first); schema_free(rest);
        if (!err[0]) snprintf(err, errcap, "out of memory compiling parallel calls");
        return NULL;
    }
    atem_seq_add(root, first);
    atem_seq_add(root, rest);
    root->whitespace_significant = true;
    return root;
}

snode *schema_compile_qwen_parallel(jv *tools, const char *only_tool,
                                    char *err, int errcap) {
    err[0] = 0;
    return native_parallel_calls(qwen_call, tools, only_tool, err, errcap);
}

// ----------------------------------------------------- Nemotron Nano tools

// One entry of Nemotron Nano's call list: `{"name": "N", "arguments": {...}}`,
// the name chosen from the declared tools and the arguments compiled from its
// schema exactly as the Qwen JSON call's are.
static snode *nemo_entry(jv *tools, const char *only, const char *fam,
                         char *err, int errcap) {
    int selected = 0;
    for (int i = 0; i < tools->n; i++) {
        jv *fn = jv_get(tools->items[i], "function");
        if (!fn) fn = tools->items[i];
        const char *name = jv_str(jv_get(fn, "name"), NULL);
        if (!only || (name && !strcmp(name, only))) selected++;
    }
    if (!selected) { snprintf(err, errcap, "named %s tool is not declared", fam); return NULL; }
    snode *root = atem_seq(3);
    snode *names = sn_new(SN_ENUM), *choice = sn_new(SN_COND);
    if (!root || !names || !choice) goto fail;
    names->lits = calloc((size_t)selected, sizeof(*names->lits));
    choice->alts = calloc((size_t)selected, sizeof(*choice->alts));
    if (!names->lits || !choice->alts) goto fail;
    names->min_items = 1;
    names->whitespace_significant = choice->whitespace_significant = true;
    root->whitespace_significant = true;
    if (!atem_seq_add(root, atem_lit("{\"name\": \""))) goto fail;
    for (int i = 0; i < tools->n; i++) {
        jv *fn = jv_get(tools->items[i], "function");
        if (!fn) fn = tools->items[i];
        const char *name = jv_str(jv_get(fn, "name"), NULL);
        if (!name || !name[0]) { snprintf(err, errcap, "%s tool %d has no function name", fam, i); goto fail; }
        if (only && strcmp(name, only)) continue;
        if (!(names->lits[names->n_lits] = strdup(name))) goto fail;
        names->n_lits++;
        if (!(choice->alts[choice->n_alts] = qwen_call_tail(tools->items[i], "}", err, errcap)))
            goto fail;
        choice->n_alts++;
    }
    if (!enum_index(names) || !atem_seq_add(root, names)) goto fail;
    names = NULL;
    if (!atem_seq_add(root, choice)) goto fail;
    return root;
fail:
    schema_free(names); schema_free(choice); schema_free(root);
    if (!err[0]) snprintf(err, errcap, "out of memory compiling %s call", fam);
    return NULL;
}

// After an entry: close the list, or (while `remaining`) a separator and the
// next entry. The two branches open with different bytes (`]` and `,`).
static snode *nemo_rest(jv *tools, const char *only, const char *fam,
                        const char *close, int remaining, char *err, int errcap) {
    snode *end = atem_lit(close);
    if (!end || !remaining) return end;
    snode *seq = atem_seq(3), *u = sn_new(SN_UNION);
    snode *entry = seq ? nemo_entry(tools, only, fam, err, errcap) : NULL;
    snode *tail = entry ? nemo_rest(tools, only, fam, close, remaining - 1, err, errcap) : NULL;
    if (!seq || !u || !entry || !tail || !(u->alts = calloc(2, sizeof(*u->alts))) ||
        !atem_seq_add(seq, atem_lit(", "))) {
        schema_free(seq); schema_free(u); schema_free(entry); schema_free(tail); schema_free(end);
        if (!err[0]) snprintf(err, errcap, "out of memory compiling Nemotron calls");
        return NULL;
    }
    atem_seq_add(seq, entry);
    atem_seq_add(seq, tail);
    seq->whitespace_significant = u->whitespace_significant = true;
    u->alts[u->n_alts++] = end;
    u->alts[u->n_alts++] = seq;
    return u;
}

// A required or named Nemotron Nano turn: one `<TOOLCALL>[...]</TOOLCALL>`
// block, one entry, or up to NATIVE_PARALLEL_MAX_CALLS when parallel. The
// opener may follow the blank line a reasoning model writes after `</think>`
// (native_lead_lit). The turn end after the block is the model's own stop.
snode *schema_compile_nemotron_turn(jv *tools, const char *only_tool,
                                    bool parallel, char *err, int errcap) {
    err[0] = 0;
    if (!tools || tools->type != J_ARR || tools->n <= 0 || tools->n > 60) {
        snprintf(err, errcap, "Nemotron tools must be a non-empty array of at most 60 tools");
        return NULL;
    }
    snode *root = atem_seq(3);
    snode *open = root ? native_lead_lit("<TOOLCALL>[") : NULL;
    snode *entry = open ? nemo_entry(tools, only_tool, "Nemotron", err, errcap) : NULL;
    snode *rest = entry ? nemo_rest(tools, only_tool, "Nemotron", "]</TOOLCALL>",
                                    parallel ? NATIVE_PARALLEL_MAX_CALLS - 1 : 0,
                                    err, errcap) : NULL;
    if (!root || !open || !entry || !rest) {
        schema_free(root); schema_free(open); schema_free(entry); schema_free(rest);
        if (!err[0]) snprintf(err, errcap, "out of memory compiling Nemotron turn");
        return NULL;
    }
    atem_seq_add(root, open);
    atem_seq_add(root, entry);
    atem_seq_add(root, rest);
    root->whitespace_significant = true;
    return root;
}

// ----------------------------------------------------- Mistral tools

// The list after Mistral's `[TOOL_CALLS]`: `[` (Nemo) or ` [` (v0.3, and
// what a Nemo file carrying the v0.3 template writes), entries as Nemotron's,
// closed by the bare `]`. The turn ends there: the model writes no eos after
// the list on v0.3, so the constraint's own end stops it.
static snode *mistral_list(jv *tools, const char *only, bool parallel,
                           char *err, int errcap) {
    snode *root = atem_seq(3), *open = sn_new(SN_ENUM);
    snode *entry = NULL, *rest = NULL;
    if (!root || !open || !(open->lits = calloc(2, sizeof(*open->lits))))
        goto fail;
    open->lits[open->n_lits++] = strdup("[");
    open->lits[open->n_lits++] = strdup(" [");
    if (!open->lits[0] || !open->lits[1]) goto fail;
    open->min_items = 1;
    open->whitespace_significant = true;
    if (!enum_index(open)) goto fail;
    entry = nemo_entry(tools, only, "Mistral", err, errcap);
    rest = entry ? nemo_rest(tools, only, "Mistral", "]",
                             parallel ? NATIVE_PARALLEL_MAX_CALLS - 1 : 0,
                             err, errcap) : NULL;
    if (!entry || !rest) goto fail;
    atem_seq_add(root, open);
    atem_seq_add(root, entry);
    atem_seq_add(root, rest);
    root->whitespace_significant = true;
    return root;
fail:
    schema_free(root); schema_free(open); schema_free(entry); schema_free(rest);
    if (!err[0]) snprintf(err, errcap, "out of memory compiling Mistral turn");
    return NULL;
}

// A Mistral v0.3 or Nemo turn. Required or named: `[TOOL_CALLS]` and the
// list. Auto: prose ending at the model's stop, or handing off to the list
// at the full `[TOOL_CALLS]`; with a response_format, that schema instead of
// the prose (its `{` cannot open the marker).
snode *schema_compile_mistral_turn(jv *tools, bool allow_text,
                                   const char *only_tool, jv *final_schema,
                                   bool parallel, char *err, int errcap) {
    err[0] = 0;
    if (!tools || tools->type != J_ARR || tools->n <= 0 || tools->n > 60) {
        snprintf(err, errcap, "Mistral tools must be a non-empty array of at most 60 tools");
        return NULL;
    }
    snode *list = mistral_list(tools, only_tool, parallel, err, errcap);
    if (!list) return NULL;
    if (allow_text && !final_schema) {
        snode *raw = atem_raw("</s>");
        if (!raw || !(raw->lits = calloc(1, sizeof(*raw->lits))) ||
            !(raw->alts = calloc(1, sizeof(*raw->alts))) ||
            !(raw->lits[0] = strdup("[TOOL_CALLS]"))) {
            schema_free(raw); schema_free(list);
            snprintf(err, errcap, "out of memory compiling Mistral turn");
            return NULL;
        }
        raw->n_lits = 1;
        raw->alts[raw->n_alts++] = list;
        raw->whitespace_significant = true;
        return raw;
    }
    snode *call = atem_seq(2);
    if (!call || !atem_seq_add(call, atem_lit("[TOOL_CALLS]"))) {
        schema_free(call); schema_free(list);
        snprintf(err, errcap, "out of memory compiling Mistral turn");
        return NULL;
    }
    atem_seq_add(call, list);
    call->whitespace_significant = true;
    if (!allow_text) return call;
    snode *final = compile_node(final_schema, err, errcap, 0);
    snode *root = final ? sn_new(SN_UNION) : NULL;
    if (!root || !(root->alts = calloc(2, sizeof(*root->alts)))) {
        schema_free(call); schema_free(final); schema_free(root);
        if (!err[0]) snprintf(err, errcap, "out of memory compiling Mistral turn");
        return NULL;
    }
    root->whitespace_significant = true;
    root->alts[root->n_alts++] = call;
    root->alts[root->n_alts++] = final;
    return root;
}

// XML parameter lists use the existing ordered native-member automaton.
// Strings are raw text; all other values retain JSON's own schema machine.
static snode *coder_call_tail(jv *tool, char *err, int errcap) {
    jv *fn=jv_get(tool,"function");if (!fn) fn=tool;
    jv *params=jv_get(fn,"parameters"), *props=jv_get(params,"properties");
    if (props && (props->type!=J_OBJ || props->n>60)) {
        snprintf(err,errcap,"Qwen3-Coder parameters must be an object with at most 60 properties");return NULL;
    }
    snode *seq=atem_seq(2), *members=native_members_new(props?props->n:0,"</function>\n</tool_call>");
    if (!seq || !members) { schema_free(seq);schema_free(members);return NULL; }
    for (int i=0;props && i<props->n;i++) {
        jv *spec=props->items[i];
        const char *type=jv_str(jv_get(spec,"type"),"");
        bool raw=false;
        snode *value=NULL;
        if (!strcmp(type,"string")) {
            value=atem_string_value(spec,props->keys[i],&raw,err,errcap);
            // the raw-string helper is atem's and names atem in its refusal;
            // this family's syntax has the same limit, stated in its own name
            if (!value && !strncmp(err,"atem raw string",15))
                snprintf(err,errcap,"Qwen3-Coder string parameter '%s' carries a "
                         "length or pattern constraint its raw-text syntax cannot "
                         "enforce",props->keys[i]);
            if (value && raw) {
                // The closing tag itself, not `\n</parameter>`: Qwen3-Coder
                // 30B-A3B at its own temperature closes with ` </parameter>`
                // or `\n\n </parameter>` as often as with the reference's
                // newline, and a sentinel that requires the newline lets the
                // value run on through the tags and into the next call until
                // a bare `\n</parameter>` happens. The parser strips the one
                // framing newline where the model wrote it (coder_one_call).
                free(value->sentinel);value->sentinel=strdup("</parameter>");
                value->sentinel_len=12;
                if (!value->sentinel) { schema_free(value);value=NULL; }
            } else if (value) {
                // an enum-valued string is spelled exactly, no JSON
                // whitespace before it: the parser reads the bytes as written
                value->whitespace_significant=true;
                for (int j=0;j<value->n_lits;j++)
                    if (strstr(value->lits[j],"</parameter>")) {
                        snprintf(err,errcap,"Qwen3-Coder string enum contains its closing delimiter");
                        schema_free(value);value=NULL;break;
                    }
            }
        } else value=compile_node(spec,err,errcap,0);
        snode *tail=atem_seq(raw?2:3);
        sbuf open={0};sb_fmt(&open,"<parameter=%s>\n",props->keys[i]);
        if (!tail || !value || open.failed || !atem_seq_add(tail,value) ||
            (!raw && !atem_seq_add(tail,atem_lit("\n</parameter>"))) ||
            !atem_seq_add(tail,atem_lit("\n")) ||
            !native_member_set(members,i,open.s,open.s,tail)) {
            if (!tail || !tail->n_props) schema_free(value);
            schema_free(tail);free(open.s);schema_free(members);schema_free(seq);return NULL;
        }
        free(open.s);
    }
    if (props && !native_members_required(members,params,props,NULL,err,errcap)) {
        schema_free(members);schema_free(seq);return NULL;
    }
    if (!atem_seq_add(seq,atem_lit(">\n"))) { schema_free(members);schema_free(seq);return NULL; }
    atem_seq_add(seq,members);return seq;
}

static snode *coder_call(jv *tools, const char *only, bool lead, char *err, int errcap) {
    snode *seq=atem_seq(3), *names=sn_new(SN_ENUM), *choice=sn_new(SN_COND);
    if (!seq || !names || !choice) goto bad;
    names->lits=calloc((size_t)tools->n,sizeof(*names->lits));
    choice->alts=calloc((size_t)tools->n,sizeof(*choice->alts));
    if (!names->lits || !choice->alts) goto bad;
    // no insignificant whitespace anywhere in the native syntax: the walker
    // would otherwise take a newline after the name for JSON whitespace at
    // the node that follows it (the choice), and `<function=f\n>` is not a
    // declaration the parser knows
    names->min_items=1;names->whitespace_significant=true;choice->whitespace_significant=true;
    for (int i=0;i<tools->n;i++) {
        jv *fn=jv_get(tools->items[i],"function");if (!fn) fn=tools->items[i];
        const char *name=jv_str(jv_get(fn,"name"),NULL);
        if (!name || !*name || strchr(name,'>') || strchr(name,'\n')) {
            snprintf(err,errcap,"invalid Qwen3-Coder function name");goto bad;
        }
        if (only && strcmp(only,name)) continue;
        names->lits[names->n_lits]=strdup(name);
        if (!names->lits[names->n_lits++]) goto bad;
        snode *tail=coder_call_tail(tools->items[i],err,errcap);
        if (!tail) goto bad;
        choice->alts[choice->n_alts++]=tail;
    }
    if (!names->n_lits) { snprintf(err,errcap,"named Qwen3-Coder tool is not declared");goto bad; }
    if (!enum_index(names) ||
        !atem_seq_add(seq,lead?native_lead_lit("<tool_call>\n<function="):atem_lit("\n<function="))) goto bad;
    atem_seq_add(seq,names);atem_seq_add(seq,choice);return seq;
bad:
    schema_free(seq);schema_free(names);schema_free(choice);
    if (!err[0]) snprintf(err,errcap,"out of memory compiling Qwen3-Coder call");
    return NULL;
}

static snode *coder_text_calls(jv *tools, const char *only, int left, char *err, int errcap) {
    if (!left) return atem_raw_bounded("<|im_end|>", NATIVE_END_BYTES);
    snode *seq=atem_seq(2), *call=coder_call(tools,only,false,err,errcap);
    snode *tail=call ? coder_text_calls(tools,only,left-1,err,errcap) : NULL;
    if (!seq || !call || !tail) { schema_free(seq);schema_free(call);schema_free(tail);return NULL; }
    atem_seq_add(seq,call);atem_seq_add(seq,tail);return qwen_text_handoff(seq);
}

snode *schema_compile_qwen_xml_turn(jv *tools, bool allow_final,
                                    const char *only, jv *final_schema,
                                    bool parallel, char *err, int errcap) {
    err[0]=0;
    if (!tools || tools->type!=J_ARR || !tools->n || tools->n>60) {
        snprintf(err,errcap,"Qwen3-Coder requires 1..60 tool declarations");return NULL;
    }
    if (allow_final && !final_schema) return coder_text_calls(tools,only,parallel?8:1,err,errcap);
    snode *call=coder_call(tools,only,true,err,errcap);
    if (!call) return NULL;
    if (allow_final) return qwen_or_final(call,final_schema,err,errcap);
    if (!parallel) return call;
    schema_free(call);
    return native_parallel_calls(coder_call, tools, only, err, errcap);
}

snode *schema_compile_muse_user_payload(struct jv *schema,
                                        char *err, int errcap) {
    err[0] = 0;
    snode *root = sn_new(SN_UNION);
    snode *direct = atem_seq(2), *after = atem_seq(2);
    snode *p1 = compile_node(schema, err, errcap, 0);
    snode *p2 = compile_node(schema, err, errcap, 0);
    if (!root || !direct || !after || !p1 || !p2) goto fail;
    root->alts = calloc(2, sizeof(*root->alts));
    if (!root->alts) goto fail;
    root->whitespace_significant = true;
    direct->whitespace_significant = true;
    direct->props[direct->n_props++] = atem_lit(" to=user<|message|>");
    after->props[after->n_props++] = atem_lit("user<|message|>");
    if (!direct->props[0] || !after->props[0]) goto fail;
    direct->props[direct->n_props++] = p1; p1 = NULL;
    after->props[after->n_props++] = p2; p2 = NULL;
    root->alts[root->n_alts++] = direct; direct = NULL;
    root->alts[root->n_alts++] = after; after = NULL;
    return root;
fail:
    schema_free(p1); schema_free(p2);
    schema_free(direct); schema_free(after); schema_free(root);
    if (!err[0]) snprintf(err, errcap, "out of memory compiling Muse user payload");
    return NULL;
}

static snode *harmony_call_select(jv *tools, const char *only_tool,
                                  const char *prefix,
                                  char *err, int errcap) {
    int selected = 0;
    for (int i = 0; i < tools->n; i++) {
        jv *fn = jv_get(tools->items[i], "function");
        const char *name = jv_str(jv_get(fn, "name"), NULL);
        if (name && (!only_tool || !strcmp(name, only_tool))) selected++;
    }
    if (!selected) {
        snprintf(err, errcap, only_tool
                 ? "named Harmony tool is not declared"
                 : "Harmony tools have no function names");
        return NULL;
    }
    snode *root = atem_seq(prefix ? 3 : 2);
    snode *names = sn_new(SN_ENUM), *choice = sn_new(SN_COND);
    if (!root || !names || !choice) goto fail;
    names->lits = calloc((size_t)selected, sizeof(*names->lits));
    choice->alts = calloc((size_t)selected, sizeof(*choice->alts));
    if (!names->lits || !choice->alts) goto fail;
    names->min_items = 1;
    names->whitespace_significant = true;
    choice->whitespace_significant = true;
    if (prefix && !atem_seq_add(root, atem_lit(prefix))) goto fail;
    for (int i = 0; i < tools->n; i++) {
        jv *fn = jv_get(tools->items[i], "function");
        const char *name = jv_str(jv_get(fn, "name"), NULL);
        if (!name || (only_tool && strcmp(name, only_tool))) continue;
        names->lits[names->n_lits] = strdup(name);
        if (!names->lits[names->n_lits]) goto fail;
        names->n_lits++;
        snode *tail = atem_seq(2);
        jv *params = jv_get(fn, "parameters");
        snode *args = params ? compile_node(params, err, errcap, 0)
                             : atem_lit("{}");
        if (!tail || !args ||
            !atem_seq_add(tail,
                          atem_lit("<|constrain|>json<|message|>")) ||
            !atem_seq_add(tail, args)) {
            schema_free(args); schema_free(tail);
            if (err[0]) goto fail;
            goto fail;
        }
        tail->whitespace_significant = true;
        choice->alts[choice->n_alts++] = tail;
    }
    if (!atem_seq_add(root, names)) goto fail;
    names = NULL;
    if (!atem_seq_add(root, choice)) goto fail;
    choice = NULL;
    root->whitespace_significant = true;
    return root;
fail:
    if (!err[0]) snprintf(err, errcap, "out of memory compiling Harmony call");
    schema_free(names); schema_free(choice); schema_free(root);
    return NULL;
}

static snode *harmony_after_reasoning(jv *tools, const char *only_tool,
                                     bool allow_final, jv *final_schema,
                                     char *err, int errcap) {
    int count = allow_final ? 2 : 1;
    snode *root = atem_seq(4), *names = sn_new(SN_ENUM), *choice = sn_new(SN_COND);
    if (!root || !names || !choice) goto fail;
    names->lits = calloc((size_t)count, sizeof(*names->lits));
    choice->alts = calloc((size_t)count, sizeof(*choice->alts));
    if (!names->lits || !choice->alts) goto fail;
    names->min_items = 1;
    names->whitespace_significant = choice->whitespace_significant = true;
    names->lits[names->n_lits++] = strdup("commentary");
    choice->alts[choice->n_alts++] = harmony_call_select(
        tools, only_tool, " to=functions.", err, errcap);
    if (!names->lits[0] || !choice->alts[0]) goto fail;
    if (allow_final) {
        names->lits[names->n_lits++] = strdup("final");
        choice->alts[choice->n_alts++] = atem_seq(2);
        snode *branch = choice->alts[1];
        snode *body = final_schema ? compile_node(final_schema, err, errcap, 0)
                                   : atem_raw("<|return|>");
        if (!names->lits[1] || !branch || !body ||
            !atem_seq_add(branch, atem_lit("<|message|>")) ||
            !atem_seq_add(branch, body)) {
            schema_free(body); goto fail;
        }
        branch->whitespace_significant = true;
    }
    if (!atem_seq_add(root, atem_lit("<|message|>")) ||
        // gpt-oss can narrate the intended call indefinitely when a required
        // turn masks its final-answer branch. Keep enough native analysis for
        // an ordinary plan, then make the trained handoff the only legal next
        // token so the request budget still reaches the model-generated args.
        // The bound is load-bearing on the auto branch too, not only when the
        // final answer is masked. Lifting it there was tried and measured on
        // gpt-oss-20b (2026-08-14): a JSON tool result made the model deliberate
        // past 1.7 kB about the call it had already answered, exhaust the token
        // budget, and emit `{"city":"","units":"celsius"}` with
        // finish_reason "length" — over six rounds it never terminated. Bounded,
        // the same history costs one redundant call and then answers.
        !atem_seq_add(root, atem_raw_bounded(
            "<|end|><|start|>assistant<|channel|>", 192)) ||
        !atem_seq_add(root, names) || !atem_seq_add(root, choice)) goto fail;
    names = choice = NULL;
    root->whitespace_significant = true;
    return root;
fail:
    schema_free(names); schema_free(choice); schema_free(root);
    if (!err[0]) snprintf(err, errcap, "out of memory compiling Harmony reasoning");
    return NULL;
}

static snode *harmony_full_call(jv *tools, const char *only_tool,
                                char *err, int errcap) {
    snode *root = atem_seq(2);
    snode *call = harmony_call_select(
        tools, only_tool, " to=functions.", err, errcap);
    if (!root || !call ||
        !atem_seq_add(root, atem_lit("<|channel|>commentary")) ||
        !atem_seq_add(root, call)) {
        schema_free(call); schema_free(root);
        return NULL;
    }
    root->whitespace_significant = true;
    return root;
}

static snode *harmony_commentary_tail(jv *tools, const char *only_tool,
                                      bool allow_preamble,
                                      char *err, int errcap) {
    snode *direct = harmony_call_select(
        tools, only_tool, " to=functions.", err, errcap);
    if (!allow_preamble) return direct;
    snode *root = sn_new(SN_UNION), *preamble = atem_seq(3);
    snode *call = harmony_full_call(tools, only_tool, err, errcap);
    if (!root || !preamble || !direct || !call) goto fail;
    root->alts = calloc(2, sizeof(*root->alts));
    if (!root->alts ||
        !atem_seq_add(preamble, atem_lit("<|message|>")) ||
        !atem_seq_add(preamble, atem_raw_bounded(
            "<|end|><|start|>assistant", 192)) ||
        !atem_seq_add(preamble, call)) goto fail;
    call = NULL;
    preamble->whitespace_significant = root->whitespace_significant = true;
    root->alts[root->n_alts++] = direct; direct = NULL;
    root->alts[root->n_alts++] = preamble; preamble = NULL;
    return root;
fail:
    schema_free(direct); schema_free(call); schema_free(preamble); schema_free(root);
    {
        if (!err[0]) snprintf(err, errcap, "out of memory compiling Harmony commentary");
        return NULL;
    }
}

static snode *harmony_channel_select(jv *tools, const char *only_tool,
                                     bool allow_final, jv *final_schema,
                                     bool allow_reasoning,
                                     char *err, int errcap) {
    int count = 1 + (allow_reasoning ? 1 : 0) + (allow_final ? 1 : 0);
    snode *root = atem_seq(3), *names = sn_new(SN_ENUM), *choice = sn_new(SN_COND);
    if (!root || !names || !choice) goto fail;
    names->lits = calloc((size_t)count, sizeof(*names->lits));
    choice->alts = calloc((size_t)count, sizeof(*choice->alts));
    if (!names->lits || !choice->alts) goto fail;
    names->min_items = 1;
    names->whitespace_significant = choice->whitespace_significant = true;
#define HARMONY_CHANNEL(NAME, NODE) do {                                      \
        choice->alts[choice->n_alts++] = (NODE);                              \
        names->lits[names->n_lits++] = strdup(NAME);                          \
        if (!choice->alts[choice->n_alts - 1] ||                              \
            !names->lits[names->n_lits - 1]) goto fail;                       \
    } while (0)
    if (allow_reasoning) {
        snode *branch = harmony_after_reasoning(
            tools, only_tool, allow_final, final_schema, err, errcap);
        HARMONY_CHANNEL("analysis", branch);
    }
    {
        snode *branch = harmony_commentary_tail(
            tools, only_tool, allow_final, err, errcap);
        HARMONY_CHANNEL("commentary", branch);
    }
    if (allow_final) {
        snode *branch = atem_seq(2);
        snode *body = final_schema ? compile_node(final_schema, err, errcap, 0)
                                   : atem_raw("<|return|>");
        if (!branch || !body || !atem_seq_add(branch, atem_lit("<|message|>")) ||
            !atem_seq_add(branch, body)) {
            schema_free(body); schema_free(branch); goto fail;
        }
        branch->whitespace_significant = true;
        HARMONY_CHANNEL("final", branch);
    }
#undef HARMONY_CHANNEL
    if (!atem_seq_add(root, atem_lit("<|channel|>")) ||
        !atem_seq_add(root, names) || !atem_seq_add(root, choice)) goto fail;
    names = choice = NULL;
    root->whitespace_significant = true;
    return root;
fail:
    schema_free(names); schema_free(choice); schema_free(root);
    if (!err[0]) snprintf(err, errcap, "out of memory compiling Harmony channels");
    return NULL;
}

snode *schema_compile_harmony_turn(jv *tools, bool allow_final,
                                   const char *only_tool, jv *final_schema,
                                   bool allow_reasoning,
                                   char *err, int errcap) {
    err[0] = 0;
    if (!tools || tools->type != J_ARR || tools->n <= 0 || tools->n > 60) {
        snprintf(err, errcap,
                 "Harmony tools must be a non-empty array of at most 60 tools");
        return NULL;
    }
    snode *root = harmony_channel_select(
        tools, only_tool, allow_final, final_schema, allow_reasoning,
        err, errcap);
    if (root) return root;
    if (!err[0]) snprintf(err, errcap, "out of memory compiling Harmony turn");
    return NULL;
}

// ------------------------------------------------------------------ gemma4
//
// gemma4's native call is `<|tool_call>call:NAME{key:VALUE,...}<tool_call|>`,
// with values in the reference's format_argument spelling (jinja:124-155,
// transliterated in template.c): strings delimited by the reserved <|"|>
// token rather than quotes, object keys UNQUOTED, numbers and booleans bare.
//
// This is compiled instead of leaving gemma4 on runner's generic JSON
// envelope, and the reason is not conformance for its own sake: `env != NULL`
// is what buys constrained decoding, and constrained decoding is what buys
// forced-truncation recovery, streamed tool-call deltas and tool_choice
// enforcement. Taking gemma4 off the strict path to reach its native prompt
// syntax -- the cheap version of this change -- would have surrendered all
// three, and the conformance gate would have gone green while it happened.
// So the envelope stays and its GRAMMAR changes, which is what muse and
// harmony already do.
//
// One limitation is deliberate: a parameter with no declared `type` is
// refused rather than admitted as free JSON. There is no native spelling to
// constrain it to; the error names the parameter, so a caller can type it and
// retry.
#define G4_MAX_ITEMS 24      // bounded array: an unbounded one under a token
                             // budget is a truncation waiting to happen
#define G4_MAX_DEPTH 6
// An array here is compiled by REPLICATING the element grammar once per
// admissible position, so nested arrays multiply: with the 24-item default,
// three levels is 14,425 element expansions, four is 346,201, and six --
// which G4_MAX_DEPTH admits -- is 2*10^8, roughly 160 GB of snodes. tools[]
// is request data, so that is a client choosing how much of this process's
// memory to take, and it has to be refused rather than attempted. At about
// 1.1 kB of grammar per expansion this ceiling caps one compile near 55 MB,
// which still admits three unbounded levels for a tool; past it the error
// names maxItems, which is what a caller does about it.
#define G4_MAX_EXPANSIONS 50000

static snode *g4_value(jv *schema, const char *what, int depth, int *budget,
                       char *err, int errcap);

// `[` VALUE ( `,` VALUE ){0,G4_MAX_ITEMS-1} `]`, built tail-first so every
// choice point is a UNION between `]` and something that cannot start with
// `]`. That is what makes it decidable: pick_alt resolves a union on the
// first byte, so the closing bracket and the next element must never share
// one.
static snode *g4_array(jv *schema, const char *what, int depth, int *budget,
                       char *err, int errcap) {
    jv *items = jv_get(schema, "items");
    if (!items || items->type != J_OBJ) {
        snprintf(err, errcap, "gemma4 %s is an array without an `items` schema",
                 what);
        return NULL;
    }
    int declared_max, min;
    if (!compile_bound(jv_get(schema, "maxItems"), G4_MAX_ITEMS,
                       &declared_max) ||
        !compile_bound(jv_get(schema, "minItems"), 0, &min)) {
        snprintf(err, errcap,
                 "gemma4 %s has invalid integer minItems/maxItems", what);
        return NULL;
    }
    int max = declared_max < G4_MAX_ITEMS ? declared_max : G4_MAX_ITEMS;
    if (min > max) {
        snprintf(err, errcap,
                 "gemma4 %s minItems exceeds its enforceable maxItems", what);
        return NULL;
    }
    snode *tail = atem_lit("]");
    if (!tail) return NULL;
    for (int i = max; i >= 1; i--) {
        // element i: `,`+value+tail when i > 1, bare value+tail when i == 1
        snode *value = g4_value(items, what, depth + 1, budget, err, errcap);
        snode *seq = atem_seq(3);
        if (!value || !seq) { schema_free(value); schema_free(seq); goto oom; }
        seq->whitespace_significant = true;
        if (i > 1 && !atem_seq_add(seq, atem_lit(","))) {
            schema_free(value); schema_free(seq); goto oom;
        }
        if (!atem_seq_add(seq, value) || !atem_seq_add(seq, tail)) {
            schema_free(seq); goto oom;
        }
        tail = seq;                       // `tail` is now owned by `seq`
        if (i > min) {
            // this element is optional: `]` may come instead
            snode *u = sn_new(SN_UNION);
            if (!u) goto oom;
            u->alts = calloc(2, sizeof(*u->alts));
            if (!u->alts) { schema_free(u); goto oom; }
            u->whitespace_significant = true;
            u->alts[u->n_alts++] = atem_lit("]");
            u->alts[u->n_alts++] = tail;
            if (!u->alts[0]) { schema_free(u); tail = NULL; goto oom; }
            tail = u;
        }
    }
    snode *root = atem_seq(2);
    if (!root) goto oom;
    root->whitespace_significant = true;
    if (!atem_seq_add(root, atem_lit("[")) || !atem_seq_add(root, tail)) {
        schema_free(root); goto oom;
    }
    return root;
oom:
    schema_free(tail);
    if (!err[0]) snprintf(err, errcap, "out of memory compiling gemma4 array");
    return NULL;
}

// `{` key `:` VALUE ( `,` key `:` VALUE )* `}` -- keys UNQUOTED and in
// jinja dictsort order, which is what format_argument writes. SN_MEMBERS owns
// the ordered optionality; the opening brace stays outside it so first and
// subsequent member prefixes differ only by the latter's comma.
static snode *g4_object(jv *schema, const char *what, int depth, int *budget,
                        char *err, int errcap) {
    jv *props = jv_get(schema, "properties");
    if (!props || props->type != J_OBJ) {
        snprintf(err, errcap,
                 "gemma4 %s is an object without declared `properties`",
                 what);
        return NULL;
    }
    if (props->n > 60) {
        snprintf(err, errcap, "gemma4 %s has too many properties (max 60)",
                 what);
        return NULL;
    }
    int *order = malloc(sizeof(int) * (size_t)(props->n > 0 ? props->n : 1));
    if (!order) {
        snprintf(err, errcap, "out of memory compiling gemma4 object");
        return NULL;
    }
    jv_dictsort(props, order);
    snode *seq = atem_seq(2);
    snode *members = native_members_new(props->n, "}");
    if (!seq || !members) {
        free(order); schema_free(seq); schema_free(members); goto oom;
    }
    seq->whitespace_significant = true;
    for (int i = 0; i < props->n; i++) {
        const char *key = props->keys[order[i]];
        sbuf first = {0}, next = {0};
        sb_fmt(&first, "%s:", key);
        sb_fmt(&next, ",%s:", key);
        char what2[96];
        snprintf(what2, sizeof(what2), "%s.%s", what, key);
        snode *value = g4_value(props->items[order[i]], what2, depth + 1,
                                budget, err, errcap);
        if (first.failed || next.failed || !value ||
            !native_member_set(members, i, first.s, next.s, value)) {
            free(first.s); free(next.s); schema_free(value);
            free(order); schema_free(members); schema_free(seq);
            return NULL;
        }
        free(first.s); free(next.s);
    }
    if (!native_members_required(members, schema, props, order, err, errcap)) {
        free(order); schema_free(members); schema_free(seq); return NULL;
    }
    free(order);
    if (!atem_seq_add(seq, atem_lit("{")) ||
        !atem_seq_add(seq, members)) {
        if (seq->n_props < 2) schema_free(members);
        schema_free(seq); goto oom;
    }
    return seq;
oom:
    if (!err[0]) snprintf(err, errcap, "out of memory compiling gemma4 object");
    return NULL;
}

static snode *g4_value(jv *schema, const char *what, int depth, int *budget,
                       char *err, int errcap) {
    if (depth > G4_MAX_DEPTH) {
        snprintf(err, errcap, "gemma4 %s nests deeper than %d levels",
                 what, G4_MAX_DEPTH);
        return NULL;
    }
    // one expansion is one value slot in the compiled grammar; see
    // G4_MAX_EXPANSIONS for why the count is bounded rather than trusted
    if (--*budget < 0) {
        snprintf(err, errcap,
                 "gemma4 %s expands past %d value slots: this family's native "
                 "call syntax needs one compiled slot per admissible array "
                 "element, so nested arrays multiply -- declare maxItems on "
                 "them", what, G4_MAX_EXPANSIONS);
        return NULL;
    }
    jv *ty = jv_get(schema, "type");
    const char *type = jv_str(ty, NULL);
    if (!type) {
        // `{"enum": ["c", "f"]}` is a typed parameter written without the
        // keyword, and a common one. Anything else untyped is refused: the
        // generic envelope admits it as free JSON, but format_argument has no
        // free-form spelling to constrain a native call to.
        jv *en = jv_get(schema, "enum");
        jv *cn = jv_get(schema, "const");
        bool all_str = en && en->type == J_ARR && en->n > 0;
        for (int i = 0; all_str && i < en->n; i++)
            if (!en->items[i] || en->items[i]->type != J_STR) all_str = false;
        if (all_str || (cn && cn->type == J_STR)) type = "string";
        else {
            snprintf(err, errcap,
                     "gemma4 %s has no declared `type`: this family's native "
                     "call syntax has no spelling for a free-form value, so it "
                     "cannot be constrained", what);
            return NULL;
        }
    }
    if (!strcmp(type, "string")) {
        if (jv_get(schema, "minLength") || jv_get(schema, "maxLength") ||
            jv_get(schema, "pattern")) {
            snprintf(err, errcap,
                     "gemma4 %s has string length/pattern constraints that its "
                     "native delimiter syntax cannot enforce", what);
            return NULL;
        }
        jv *en = jv_get(schema, "enum");
        jv *cn = jv_get(schema, "const");
        if (en || cn) {
            snode *json = compile_node(schema, err, errcap, 0);
            if (!json) return NULL;
            if (json->kind != SN_ENUM) {
                snprintf(err, errcap,
                         "gemma4 %s string literal schema did not compile to an enum",
                         what);
                schema_free(json);
                return NULL;
            }
            snode *n = sn_new(SN_ENUM);
            if (!n) { schema_free(json); return NULL; }
            n->lits = calloc((size_t)json->n_lits, sizeof(*n->lits));
            if (!n->lits) { schema_free(n); schema_free(json); return NULL; }
            n->whitespace_significant = true;
            for (int i = 0; i < json->n_lits; i++) {
                jv *literal = json_parse(json->lits[i], strlen(json->lits[i]));
                const char *v = jv_str(literal, NULL);
                if (!v || strstr(v, "<|\"|>")) {
                    snprintf(err, errcap,
                             "gemma4 %s has an unrepresentable native string "
                             "literal", what);
                    jv_free(literal); schema_free(n); schema_free(json);
                    return NULL;
                }
                sbuf lit = {0};
                sb_fmt(&lit, "<|\"|>%s<|\"|>", v);
                jv_free(literal);
                if (lit.failed) {
                    free(lit.s); schema_free(n); schema_free(json); return NULL;
                }
                n->lits[n->n_lits++] = lit.s;
            }
            schema_free(json);
            return n;
        }
        // The <|"|> delimiter is a reserved token, so an unconstrained value
        // between the two needs no escaping and is raw bytes up to the closer.
        snode *seq = atem_seq(2);
        // built only once there is a sequence to own it: the cleanup below
        // frees it through `seq`, so a body with no sequence is a leak (the
        // two other sites with this shape already guard it the same way)
        snode *body = !seq ? NULL : atem_raw("<|\"|>");
        if (!seq || !body || !atem_seq_add(seq, atem_lit("<|\"|>")) ||
            !atem_seq_add(seq, body)) {
            if (seq && seq->n_props < 2) schema_free(body);
            schema_free(seq);
            if (!err[0]) snprintf(err, errcap, "out of memory compiling gemma4 string");
            return NULL;
        }
        seq->whitespace_significant = true;
        return seq;
    }
    if (!strcmp(type, "boolean")) {
        snode *n = compile_node(schema, err, errcap, 0);
        if (n) n->whitespace_significant = true;
        return n;
    }
    if (!strcmp(type, "null")) {
        snode *n = compile_node(schema, err, errcap, 0);
        if (n) n->whitespace_significant = true;
        return n;
    }
    if (!strcmp(type, "integer") || !strcmp(type, "number")) {
        // Numbers are spelled identically in JSON and in format_argument, so
        // the ordinary compiler's bounded node applies unchanged -- including
        // minimum/maximum enforcement, which a raw run would drop.
        return compile_node(schema, err, errcap, 0);
    }
    if (!strcmp(type, "array"))
        return g4_array(schema, what, depth, budget, err, errcap);
    if (!strcmp(type, "object")) {
        return g4_object(schema, what, depth, budget, err, errcap);
    }
    snprintf(err, errcap, "gemma4 %s has unsupported type \"%s\"", what, type);
    return NULL;
}

// `{args}<tool_call|>` for ONE declared tool: the arguments object plus the
// block close, which is the tail the name ENUM selects.
static snode *g4_call_tail(jv *tool, int *budget, char *err, int errcap) {
    jv *fn = jv_get(tool, "function");
    if (!fn) fn = tool;
    const char *name = jv_str(jv_get(fn, "name"), "tool");
    jv *params = jv_get(fn, "parameters");
    jv *props = params ? jv_get(params, "properties") : NULL;
    if (props && props->type != J_OBJ) {
        snprintf(err, errcap, "gemma4 tool %s: parameters.properties must be "
                              "an object", name);
        return NULL;
    }
    snode *seq = atem_seq(2);
    if (!seq) goto oom;
    seq->whitespace_significant = true;
    snode *args = props && props->n
                ? g4_object(params, name, 0, budget, err, errcap)
                : atem_lit("{}");
    if (!args || !atem_seq_add(seq, args)) {
        schema_free(args); schema_free(seq);
        if (!err[0]) snprintf(err, errcap, "out of memory compiling gemma4 call");
        return NULL;
    }
    if (!atem_seq_add(seq, atem_lit("<tool_call|>"))) { schema_free(seq); goto oom; }
    return seq;
oom:
    if (!err[0]) snprintf(err, errcap, "out of memory compiling gemma4 call");
    return NULL;
}

// ENUM over the declared names, then the matching tail. `lead` is the block
// opener, which the caller has already consumed when the turn's discriminator
// covered it.
static snode *g4_call(jv *tools, const char *only_tool, bool lead,
                      int *budget, char *err, int errcap) {
    int selected = 0;
    for (int i = 0; i < tools->n; i++) {
        jv *fn = jv_get(tools->items[i], "function");
        if (!fn) fn = tools->items[i];
        const char *name = jv_str(jv_get(fn, "name"), NULL);
        if (!only_tool || (name && !strcmp(name, only_tool))) selected++;
    }
    if (!selected) {
        snprintf(err, errcap, "named gemma4 tool is not declared");
        return NULL;
    }
    snode *root = atem_seq(lead ? 3 : 2);
    snode *names = sn_new(SN_ENUM), *choice = sn_new(SN_COND);
    if (!root || !names || !choice) goto fail;
    names->lits = calloc((size_t)selected, sizeof(*names->lits));
    choice->alts = calloc((size_t)selected, sizeof(*choice->alts));
    if (!names->lits || !choice->alts) goto fail;
    names->min_items = 1;            // this enum selects the following SN_COND
    names->whitespace_significant = true;
    choice->whitespace_significant = true;
    root->whitespace_significant = true;
    if (lead && !atem_seq_add(root, atem_lit("<|tool_call>call:"))) goto fail;
    for (int i = 0; i < tools->n; i++) {
        jv *fn = jv_get(tools->items[i], "function");
        if (!fn) fn = tools->items[i];
        const char *name = jv_str(jv_get(fn, "name"), NULL);
        if (!name || !name[0]) {
            snprintf(err, errcap, "gemma4 tool %d has no function name", i);
            goto fail;
        }
        if (only_tool && strcmp(name, only_tool)) continue;
        names->lits[names->n_lits] = strdup(name);
        if (!names->lits[names->n_lits]) goto fail;
        names->n_lits++;
        choice->alts[choice->n_alts] = g4_call_tail(tools->items[i], budget,
                                                    err, errcap);
        if (!choice->alts[choice->n_alts]) goto fail;
        choice->n_alts++;
    }
    if (!enum_index(names)) goto fail;
    if (!atem_seq_add(root, names)) goto fail;
    names = NULL;
    if (!atem_seq_add(root, choice)) goto fail;
    choice = NULL;
    return root;
fail:
    if (!err[0]) snprintf(err, errcap, "out of memory compiling gemma4 call");
    schema_free(names); schema_free(choice); schema_free(root);
    return NULL;
}

// A visible answer: raw bytes up to the turn close. As a UNION alternative it
// is the catch-all, which is exactly right -- gemma4 has no marker for "this
// turn is prose", so anything not starting the native block is prose.
// The prose answer, or the caller's schema. Free prose carries a handoff:
// Gemma 4's own format is call-first, but asked for a word before acting
// (the 2026-09-14 report's "briefly say what you are about to do, then
// list the files") the 12B QAT model writes the prose and then its native
// call, and a prose branch with no way into the call grammar left that
// call as content with the framing in it, on every preset. Seeing the full
// opener commits to the call, as Qwen's text handoff does; the engine lets
// the model spell the opener with its own control token there
// (constraint_spelling_ok).
static snode *g4_final(jv *tools, const char *only_tool, jv *final_schema,
                       int *budget, char *err, int errcap) {
    if (final_schema) return compile_node(final_schema, err, errcap, 0);
    snode *n = atem_raw("<turn|>");
    if (!n) { snprintf(err, errcap, "out of memory compiling gemma4 answer"); return NULL; }
    snode *call = tools ? g4_call(tools, only_tool, false, budget, err, errcap) : NULL;
    if (tools && !call) { schema_free(n); return NULL; }
    if (call) {
        n->lits = calloc(1, sizeof(*n->lits));
        n->alts = calloc(1, sizeof(*n->alts));
        if (!n->lits || !n->alts || !(n->lits[0] = strdup("<|tool_call>call:"))) {
            schema_free(call); schema_free(n);
            snprintf(err, errcap, "out of memory compiling gemma4 answer");
            return NULL;
        }
        n->n_lits = 1; n->alts[0] = call; n->n_alts = 1;
        n->whitespace_significant = true;
    }
    return n;
}

static snode *g4_body(jv *tools, bool allow_final, const char *only_tool,
                      jv *final_schema, int *budget, char *err, int errcap) {
    snode *call = g4_call(tools, only_tool, true, budget, err, errcap);
    if (!call || !allow_final) return call;
    snode *fin = g4_final(tools, only_tool, final_schema, budget, err, errcap);
    snode *u = fin ? sn_new(SN_UNION) : NULL;
    if (u) u->alts = calloc(2, sizeof(*u->alts));
    if (!u || !u->alts) {
        schema_free(call); schema_free(fin); schema_free(u);
        if (!err[0]) snprintf(err, errcap, "out of memory compiling gemma4 turn");
        return NULL;
    }
    u->whitespace_significant = true;
    // call FIRST: the union resolves on the first byte, and only the call
    // block can start with '<'. A prose answer takes the raw branch.
    u->alts[u->n_alts++] = call;
    u->alts[u->n_alts++] = fin;
    return u;
}

snode *schema_compile_gemma4_turn(jv *tools, bool allow_final,
                                  const char *only_tool, jv *final_schema,
                                  bool allow_reasoning, bool primed_reasoning,
                                  char *err, int errcap) {
    err[0] = 0;
    if (!tools || tools->type != J_ARR || tools->n <= 0 || tools->n > 60) {
        snprintf(err, errcap,
                 "gemma4 tools must be a non-empty array of at most 60 tools");
        return NULL;
    }
    // One budget for the whole turn, not one per tool or per branch: a turn
    // that admits reasoning compiles the call grammar twice, and the ceiling
    // is on what this request costs, not on what each piece of it costs.
    int budget = G4_MAX_EXPANSIONS;
    // The prompt already opened `<|channel>thought\n` (a tool-result
    // continuation with thinking on -- template.c's g4_prev == 2 branch), so
    // the turn starts INSIDE the thought and the only question is where it
    // closes.
    if (primed_reasoning) {
        snode *seq = atem_seq(2);
        snode *rest = seq ? g4_body(tools, allow_final, only_tool, final_schema,
                                    &budget, err, errcap) : NULL;
        if (!seq || !rest || !atem_seq_add(seq, atem_raw("<channel|>")) ||
            !atem_seq_add(seq, rest)) {
            if (seq && seq->n_props < 2) schema_free(rest);
            schema_free(seq);
            if (!err[0]) snprintf(err, errcap, "out of memory compiling gemma4 turn");
            return NULL;
        }
        seq->whitespace_significant = true;
        return seq;
    }
    if (!allow_reasoning)
        return g4_body(tools, allow_final, only_tool, final_schema, &budget,
                       err, errcap);
    // Thought and call blocks BOTH open with '<', so they cannot be two
    // alternatives of a union -- pick_alt would resolve on that byte and the
    // second would be unreachable. One ENUM discriminates them instead, and
    // the union below is left with a single '<' branch against prose.
    snode *marked = atem_seq(2);
    snode *disc = sn_new(SN_ENUM), *choice = sn_new(SN_COND);
    snode *thought = NULL, *call = NULL;
    if (!marked || !disc || !choice) goto fail;
    disc->lits = calloc(2, sizeof(*disc->lits));
    choice->alts = calloc(2, sizeof(*choice->alts));
    if (!disc->lits || !choice->alts) goto fail;
    disc->min_items = 1;
    disc->whitespace_significant = true;
    choice->whitespace_significant = true;
    marked->whitespace_significant = true;
    disc->lits[disc->n_lits++] = strdup("<|channel>thought\n");
    disc->lits[disc->n_lits++] = strdup("<|tool_call>call:");
    if (!disc->lits[0] || !disc->lits[1]) goto fail;
    if (!enum_index(disc)) goto fail;
    thought = atem_seq(2);
    snode *after = thought ? g4_body(tools, allow_final, only_tool,
                                     final_schema, &budget, err, errcap) : NULL;
    if (!thought || !after ||
        !atem_seq_add(thought, atem_raw("<channel|>")) ||
        !atem_seq_add(thought, after)) {
        if (thought && thought->n_props < 2) schema_free(after);
        goto fail;
    }
    thought->whitespace_significant = true;
    call = g4_call(tools, only_tool, false, &budget, err, errcap);
    if (!call) goto fail;
    choice->alts[choice->n_alts++] = thought; thought = NULL;
    choice->alts[choice->n_alts++] = call;    call = NULL;
    if (!atem_seq_add(marked, disc)) goto fail;
    disc = NULL;
    if (!atem_seq_add(marked, choice)) goto fail;
    choice = NULL;
    if (!allow_final) return marked;
    snode *fin = g4_final(tools, only_tool, final_schema, &budget, err, errcap);
    snode *u = fin ? sn_new(SN_UNION) : NULL;
    if (u) u->alts = calloc(2, sizeof(*u->alts));
    if (!u || !u->alts) {
        schema_free(fin); schema_free(u); goto fail;
    }
    u->whitespace_significant = true;
    u->alts[u->n_alts++] = marked;
    u->alts[u->n_alts++] = fin;
    return u;
fail:
    if (!err[0]) snprintf(err, errcap, "out of memory compiling gemma4 turn");
    schema_free(thought); schema_free(call);
    schema_free(disc); schema_free(choice); schema_free(marked);
    return NULL;
}

// Two calls back to back, the bounded multi-call form. gemma4 concatenates
// call blocks with no separator, so this is simply one tail after the other.
// Can this tools[] be constrained to gemma4's native call syntax at all?
// Implemented AS the real compiler (probe and free) so the answer can never
// drift from what compilation actually accepts: an untyped parameter, an
// unbounded nested array, or any future refusal all report identically here.
// Callers use this BEFORE prompt rendering to fall back to the generic
// envelope for the whole request -- prompt and grammar must switch together.
bool schema_qwen_xml_constrainable(jv *tools, const char *only_tool,
                                   bool parallel, char *err, int errcap) {
    // the turn a required or named choice compiles: no final branch
    snode *probe = schema_compile_qwen_xml_turn(tools, false, only_tool, NULL,
                                                parallel, err, errcap);
    if (!probe) return false;
    schema_free(probe);
    return true;
}

bool schema_gemma4_constrainable(jv *tools, char *err, int errcap) {
    snode *probe = schema_compile_gemma4_turn(tools, true, NULL, NULL,
                                              true, false, err, errcap);
    if (!probe) return false;
    schema_free(probe);
    return true;
}

// After a complete gemma4 call in a parallel turn: end the turn or open the
// next call, at most `remaining` more. The same bounded raw gap as the Qwen
// protocols (native_more_calls): the model's own stop token ends the turn
// there (gemma4 closes a turn of calls with <|tool_response>, which the
// engine counts as a stop, as the publisher's generation_config does), and
// the full `<|tool_call>` opener hands off to the next call's `call:NAME`.
// Gemma4 writes consecutive calls with no separator at all.
static snode *g4_more_calls(jv *tools, const char *only, int remaining,
                            int *budget, char *err, int errcap) {
    snode *raw = atem_raw_bounded("<turn|>", remaining ? NATIVE_GAP_BYTES
                                                       : NATIVE_END_BYTES);
    if (!raw) goto oom;
    raw->whitespace_significant = true;
    if (!remaining) return raw;
    snode *seq = atem_seq(3);
    snode *open = seq ? atem_lit("call:") : NULL;
    snode *call = open ? g4_call(tools, only, false, budget, err, errcap) : NULL;
    snode *tail = call ? g4_more_calls(tools, only, remaining - 1, budget,
                                       err, errcap) : NULL;
    raw->lits = calloc(1, sizeof(*raw->lits));
    raw->alts = calloc(1, sizeof(*raw->alts));
    if (!seq || !open || !call || !tail || !raw->lits || !raw->alts ||
        !(raw->lits[0] = strdup("<|tool_call>"))) {
        schema_free(seq); schema_free(open); schema_free(call);
        schema_free(tail); schema_free(raw);
        goto oom;
    }
    raw->n_lits = 1;
    atem_seq_add(seq, open);
    atem_seq_add(seq, call);
    atem_seq_add(seq, tail);
    seq->whitespace_significant = true;
    raw->alts[raw->n_alts++] = seq;
    return raw;
oom:
    if (!err[0]) snprintf(err, errcap, "out of memory compiling parallel gemma4 turn");
    return NULL;
}

static snode *g4_parallel_calls(jv *tools, const char *only_tool, int max_calls,
                                char *err, int errcap) {
    snode *root = atem_seq(2);
    int budget = G4_MAX_EXPANSIONS;
    snode *first = root ? g4_call(tools, only_tool, true, &budget, err, errcap)
                        : NULL;
    snode *rest = first ? g4_more_calls(tools, only_tool, max_calls - 1,
                                        &budget, err, errcap) : NULL;
    if (!root || !first || !rest) {
        schema_free(first); schema_free(rest); schema_free(root);
        if (!err[0]) snprintf(err, errcap,
                              "out of memory compiling parallel gemma4 turn");
        return NULL;
    }
    root->whitespace_significant = true;
    root->props[root->n_props++] = first;
    root->props[root->n_props++] = rest;
    return root;
}

// A parallel gemma4 turn is one to NATIVE_PARALLEL_MAX_CALLS calls, each
// followed by the model's own stop or the next call (it was a fixed PAIR
// until 2026-10-09: one call to make meant inventing a second). Every call
// shares the G4_MAX_EXPANSIONS budget, so a tool whose argument grammar fit
// two copies may not fit eight; the cap then steps down (8, 4, 2, 1) rather
// than refusing a request the pair accepted.
snode *schema_compile_gemma4_parallel(jv *tools, const char *only_tool,
                                      char *err, int errcap) {
    for (int max_calls = NATIVE_PARALLEL_MAX_CALLS; ; max_calls /= 2) {
        err[0] = 0;
        snode *root = g4_parallel_calls(tools, only_tool, max_calls, err, errcap);
        if (root || max_calls <= 1 || !strstr(err, "maxItems")) return root;
    }
}
